import os,unittest,uuid,psycopg
@unittest.skipUnless(os.environ.get('BASE_CEPHEUS_DATABASE_URL'),'requires PostgreSQL')
class ShipSecurityTests(unittest.TestCase):
 def test_published_security_matrices_and_access_override(self):
  with psycopg.connect(os.environ['BASE_CEPHEUS_DATABASE_URL']) as c:
   self.assertEqual(c.execute("SELECT access_security_code,minimum_tech_level,external.name,internal.name FROM rule_ship_access_security access JOIN rule_rule external ON external.rule_id=access.external_difficulty_rule_id JOIN rule_rule internal ON internal.rule_id=access.internal_difficulty_rule_id ORDER BY access_security_code").fetchall(),[('biometrics',8,'Formidable','Very Difficult'),('electronic-lock',7,'Very Difficult','Difficult'),('intelligent',9,'Formidable','Very Difficult'),('mechanical-lock',4,'Difficult','Average')])
   self.assertEqual(c.execute('SELECT count(*) FROM src_record_provenance provenance JOIN rule_rule rule USING(rule_id) WHERE rule.rule_code=%s',('ship.security',)).fetchone()[0],6)
   with c.transaction(force_rollback=True):
    campaign=c.execute("INSERT INTO camp_campaign(name) VALUES('Security test') RETURNING campaign_id").fetchone()[0];actor=c.execute("INSERT INTO actor_actor(campaign_id,name,controller_reference) VALUES(%s,'Intruder','test') RETURNING actor_id",(campaign,)).fetchone()[0];characteristic=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='characteristic.intelligence'").fetchone()[0];skill=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='skill.mechanics'").fetchone()[0];difficulty=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='difficulty.average'").fetchone()[0];c.execute('INSERT INTO actor_characteristic(actor_id,characteristic_rule_id,maximum_value,current_value) VALUES(%s,%s,7,7)',(actor,characteristic));c.execute('INSERT INTO actor_skill(actor_id,skill_rule_id,skill_level) VALUES(%s,%s,0)',(actor,skill))
    package=c.execute("SELECT content_package_id FROM sys_content_package WHERE package_code='cepheus-engine'").fetchone()[0];item_rule=c.execute("INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status) VALUES(%s,%s,'Security Test Hull','equipment','approved') RETURNING rule_id",(package,'item.security-test-'+uuid.uuid4().hex)).fetchone()[0];c.execute("INSERT INTO inv_item_definition(rule_id,item_kind,minimum_tech_level,cost_credits) VALUES(%s,'equipment',9,1)",(item_rule,));item=c.execute("INSERT INTO inv_item_instance(campaign_id,item_rule_id,instance_name) VALUES(%s,%s,'Hull') RETURNING item_instance_id",(campaign,item_rule)).fetchone()[0];class_rule=c.execute("INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status) VALUES(%s,%s,'Security Test Ship','ship','approved') RETURNING rule_id",(package,'ship.security-test-'+uuid.uuid4().hex)).fetchone()[0];c.execute("INSERT INTO ship_class(ship_class_rule_id,class_code,hull_tons,hull_points,structure_points,minimum_tech_level,construction_cost_minor) VALUES(%s,%s,100,2,2,9,1)",(class_rule,'security-'+uuid.uuid4().hex));ship=c.execute("INSERT INTO ship_ship(campaign_id,ship_class_rule_id,inventory_item_instance_id,name,hull_current,structure_current) VALUES(%s,%s,%s,'Locked Ship',2,2) RETURNING ship_id",(campaign,class_rule,item)).fetchone()[0];point=c.execute("INSERT INTO ship_security_access_point(ship_id,campaign_id,access_security_code,access_point_name,boundary_kind) VALUES(%s,%s,'mechanical-lock','Engineering','internal') RETURNING access_point_id",(ship,campaign)).fetchone()[0]
    command=c.execute("INSERT INTO cmd_command(command_type,initiator_reference,idempotency_key,command_status,completed_at) VALUES('resolve_actor_task','test','security-override','completed',clock_timestamp()) RETURNING command_id").fetchone()[0];c.execute('INSERT INTO cmd_actor_task_receipt(command_id,actor_id,characteristic_rule_id,skill_rule_id,difficulty_rule_id,skill_modifier,characteristic_modifier,difficulty_modifier,circumstance_modifier,species_modifier,check_total,target_number,effect,succeeded) VALUES(%s,%s,%s,%s,%s,0,0,0,0,0,8,8,0,true)',(command,actor,characteristic,skill,difficulty));receipt=c.execute("INSERT INTO ship_security_override_receipt(access_point_id,task_command_id,access_state_before,access_state_after,access_version_before,access_version_after) VALUES(%s,%s,'locked','unlocked',1,2) RETURNING security_override_receipt_id",(point,command)).fetchone()[0];self.assertEqual(c.execute('SELECT access_state,concurrency_version FROM ship_security_access_point WHERE access_point_id=%s',(point,)).fetchone(),('unlocked',2))
    computer=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='skill.computer'").fetchone()[0];very_difficult=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='difficulty.very-difficult'").fetchone()[0];c.execute('INSERT INTO actor_skill(actor_id,skill_rule_id,skill_level) VALUES(%s,%s,0)',(actor,computer));c.execute('INSERT INTO ship_security_computer_state(ship_id,campaign_id,security_rating) VALUES(%s,%s,2)',(ship,campaign));cyber_command=c.execute("INSERT INTO cmd_command(command_type,initiator_reference,idempotency_key,command_status,completed_at) VALUES('resolve_actor_task','test','cyber-override','completed',clock_timestamp()) RETURNING command_id").fetchone()[0];c.execute('INSERT INTO cmd_actor_task_receipt(command_id,actor_id,characteristic_rule_id,skill_rule_id,difficulty_rule_id,skill_modifier,characteristic_modifier,difficulty_modifier,circumstance_modifier,species_modifier,check_total,target_number,effect,succeeded) VALUES(%s,%s,%s,%s,%s,0,0,0,0,0,8,8,0,true)',(cyber_command,actor,characteristic,computer,very_difficult));c.execute("INSERT INTO ship_security_cyber_attempt(ship_id,campaign_id,cybersecurity_task_code,task_command_id,security_rating_snapshot,effective_difficulty_rule_id,task_succeeded) VALUES(%s,%s,'override-security-systems',%s,2,%s,true)",(ship,campaign,cyber_command,very_difficult));self.assertEqual(c.execute('SELECT task_succeeded FROM ship_security_cyber_attempt WHERE task_command_id=%s',(cyber_command,)).fetchone()[0],True)
    compartment=c.execute("INSERT INTO ship_security_compartment(ship_id,campaign_id,compartment_name,airlock_connected) VALUES(%s,%s,'Cargo Hold',true) RETURNING security_compartment_id",(ship,campaign)).fetchone()[0];c.execute("INSERT INTO ship_security_measure_receipt(security_compartment_id,security_measure_code,initiator_actor_id,alarm_before,alarm_after,gravity_before,gravity_after,atmosphere_before,atmosphere_after,compartment_version_before,compartment_version_after) VALUES(%s,'internal-alarm',%s,false,true,1,1,'normal','normal',1,2)",(compartment,actor));c.execute("INSERT INTO ship_security_measure_receipt(security_compartment_id,security_measure_code,initiator_actor_id,alarm_before,alarm_after,gravity_before,gravity_after,atmosphere_before,atmosphere_after,compartment_version_before,compartment_version_after) VALUES(%s,'artificial-gravity',%s,true,true,1,0,'normal','normal',2,3)",(compartment,actor));c.execute("INSERT INTO ship_security_measure_receipt(security_compartment_id,security_measure_code,initiator_actor_id,alarm_before,alarm_after,gravity_before,gravity_after,atmosphere_before,atmosphere_after,compartment_version_before,compartment_version_after) VALUES(%s,'vent-atmosphere',%s,true,true,0,0,'normal','vented',3,4)",(compartment,actor));self.assertEqual(c.execute('SELECT alarm_active,gravity_g::text,atmosphere_state,concurrency_version FROM ship_security_compartment WHERE security_compartment_id=%s',(compartment,)).fetchone(),(True,'0.0','vented',4))
    passenger=c.execute("INSERT INTO ship_security_compartment(ship_id,campaign_id,compartment_name) VALUES(%s,%s,'Passenger Deck') RETURNING security_compartment_id",(ship,campaign)).fetchone()[0];endurance=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='characteristic.endurance'").fetchone()[0];average=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='difficulty.average'").fetchone()[0];c.execute('INSERT INTO actor_characteristic(actor_id,characteristic_rule_id,maximum_value,current_value) VALUES(%s,%s,7,7)',(actor,endurance));encounter_type=c.execute("SELECT rule_id FROM rule_rule WHERE rule_code='encounter.type.routine'").fetchone()[0];encounter=c.execute("INSERT INTO enc_encounter(campaign_id,encounter_type_rule_id,current_mode) VALUES(%s,%s,'personal_combat') RETURNING encounter_id",(campaign,encounter_type)).fetchone()[0];c.execute('INSERT INTO enc_personal_combat(encounter_id,current_round) VALUES(%s,1)',(encounter,));episode=c.execute('INSERT INTO ship_security_tranq_episode(security_compartment_id,encounter_id,began_combat_round) VALUES(%s,%s,1) RETURNING tranq_episode_id',(passenger,encounter)).fetchone()[0];exposure=c.execute('INSERT INTO ship_security_tranq_exposure(tranq_episode_id,actor_id) VALUES(%s,%s) RETURNING tranq_exposure_id',(episode,actor)).fetchone()[0];tranq_command=c.execute("INSERT INTO cmd_command(command_type,initiator_reference,idempotency_key,command_status,completed_at) VALUES('resolve_actor_task','test','tranq-check','completed',clock_timestamp()) RETURNING command_id").fetchone()[0];c.execute('INSERT INTO cmd_actor_task_receipt(command_id,actor_id,characteristic_rule_id,skill_rule_id,difficulty_rule_id,skill_modifier,characteristic_modifier,difficulty_modifier,circumstance_modifier,species_modifier,check_total,target_number,effect,succeeded) VALUES(%s,%s,%s,NULL,%s,0,0,0,0,0,7,8,-1,false)',(tranq_command,actor,endurance,average));c.execute('INSERT INTO ship_security_tranq_check_receipt(tranq_exposure_id,check_sequence,combat_round,task_command_id,previous_check_dm,task_succeeded,became_unconscious,exposure_version_before,exposure_version_after) VALUES(%s,1,1,%s,0,false,true,1,2)',(exposure,tranq_command));self.assertEqual(c.execute('SELECT exposure_status FROM ship_security_tranq_exposure WHERE tranq_exposure_id=%s',(exposure,)).fetchone()[0],'unconscious')
    with self.assertRaisesRegex(psycopg.errors.RaiseException,'immutable'):c.execute('DELETE FROM ship_security_override_receipt WHERE security_override_receipt_id=%s',(receipt,))
 def test_cybersecurity_rating_controls_security_override_difficulty(self):
  with psycopg.connect(os.environ['BASE_CEPHEUS_DATABASE_URL']) as c:
   self.assertEqual(c.execute("SELECT rating.security_rating,difficulty.name,rating.is_starship_default,rating.is_typical_vessel_rating FROM rule_ship_security_rating rating JOIN rule_rule difficulty ON difficulty.rule_id=rating.difficulty_rule_id ORDER BY rating.security_rating").fetchall(),[(0,'Average',True,False),(1,'Difficult',False,False),(2,'Very Difficult',False,True),(3,'Formidable',False,False)])
if __name__=='__main__':unittest.main()
